{"metadata":{"kernelspec":{"language":"python","display_name":"Python 3","name":"python3"},"language_info":{"pygments_lexer":"ipython3","nbconvert_exporter":"python","version":"3.6.4","file_extension":".py","codemirror_mode":{"name":"ipython","version":3},"name":"python","mimetype":"text/x-python"},"kaggle":{"accelerator":"none","dataSources":[],"isInternetEnabled":true,"language":"python","sourceType":"script","isGpuEnabled":false}},"nbformat_minor":4,"nbformat":4,"cells":[{"cell_type":"code","source":"# text_summarizer.py\nfrom transformers import pipeline\n\n# Load the summarization pipeline with facebook/bart-large-cnn model for abstractive summarization\nsummarizer = pipeline(\"summarization\", model=\"facebook/bart-large-cnn\")\n\ndef summarize_text(text, max_length=0.3):\n    \"\"\"\n    Summarizes the input text to 30% of its original size.\n    Args:\n        text (str): Text to be summarized.\n        max_length (float): Fraction of original length for summarization (default 30%).\n\n    Returns:\n        str: Summarized text.\n    \"\"\"\n    summary = summarizer(\n        text,\n        max_length=int(len(text) * max_length),  \n        min_length=int(len(text) * max_length * 0.8),  \n        do_sample=False\n    )\n    return summary[0]['summary_text']\n","metadata":{"_uuid":"8f2839f25d086af736a60e9eeb907d3b93b6e0e5","_cell_guid":"b1076dfc-b9ad-4769-8c92-a6c4dae69d19","trusted":true},"outputs":[],"execution_count":null}]}